codeExamples.code:
-- Compact small files and cluster by a high-cardinality filter column
OPTIMIZE main.sales.orders ZORDER BY (customer_id);

-- This query now benefits from data skipping: only files whose
-- min/max customer_id range overlaps 12345 are read.
SELECT order_id, amount, order_ts
FROM main.sales.orders
WHERE customer_id = 12345;

-- Reclaim storage from old files beyond the retention window
VACUUM main.sales.orders RETAIN 168 HOURS;

-- See every atomic commit: operation, user, and metrics
DESCRIBE HISTORY main.sales.orders;

-- Audit the table exactly as it was before a bad load (version 41)
SELECT count(*) FROM main.sales.orders VERSION AS OF 41;

-- Instantly roll the table back to the good version (no backup needed)
RESTORE TABLE main.sales.orders TO VERSION AS OF 41;
